import {test,expect} from '@playwright/test';
import {writeFileSync} from 'node:fs';
import {login,seedStorage} from '../../tests/e2e/utils';
test('Local distinct navigation/resource/parser/usability probe',async({page,context,browser})=>{
 const endpoint='/api/local-nav-q9';const off='https://local-q9.invalid';const policy="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'";
 let phase='control';const hits:{phase:string,kind:string,frame:string}[]=[];const unexpected:string[]=[];
 await context.route('**/*',async route=>{
  const u=new URL(route.request().url());
  if(u.pathname===endpoint){const kind=u.searchParams.get('k')||'unknown';let frame='unavailable';try{frame=route.request().frame().url()}catch{}hits.push({phase,kind,frame});
   if(kind==='destination')return route.fulfill({contentType:'text/html',body:`<!doctype html><h1>LOCAL_Q9_DESTINATION</h1><img src="${off}${endpoint}?k=secondary">`});
   if(kind==='parser-frame')return route.fulfill({contentType:'text/html',body:'<!doctype html><p>Parser frame</p>'});
   return route.fulfill({contentType:'image/svg+xml',body:'<svg xmlns="http://www.w3.org/2000/svg" width="2" height="2"/>'});}
  let sub=false;try{sub=route.request().frame().parentFrame()!==null}catch{}
  if(u.hostname==='local-q9.invalid'||sub){unexpected.push(u.origin+u.pathname);return route.abort()}
  return route.continue();
 });
 const canonical=`<!doctype html><html><head><style>h1{color:rgb(61,72,83)}p{margin:16px 0}</style></head><body><h1>LOCAL_Q9_READABLE</h1><p id="select">LOCAL_Q9_SELECTABLE_TEXT</p><svg width="360" height="90"><foreignObject width="350" height="80"><div xmlns="http://www.w3.org/1999/xhtml"><a id="q9-link" href="${off}${endpoint}?k=destination">LOCAL_Q9_INACTIVE_LINK</a></div></foreignObject></svg><img loading="eager" src="${off}${endpoint}?k=parser-image"><iframe src="${off}${endpoint}?k=parser-frame"></iframe>${Array.from({length:135},(_,i)=>`<p>LOCAL_Q9_ROW_${i}</p>`).join('')}<p id="end">LOCAL_Q9_END</p><script>document.documentElement.dataset.q9script='ran'</script></body></html>`;
 const preLayer=canonical.replace('<!doctype html>',`<!doctype html><meta http-equiv="Content-Security-Policy" content="${policy}">`);
 await page.setContent('<iframe id="control" sandbox="" style="width:650px;height:350px"></iframe>');
 await page.locator('#control').evaluate((e,h)=>(e as HTMLIFrameElement).srcdoc=h,preLayer);
 await expect(page.frameLocator('#control').locator('#q9-link')).toBeVisible();
 await page.frameLocator('#control').locator('#q9-link').click();
 await expect.poll(()=>hits.filter(h=>h.phase==='control'&&h.kind==='secondary').length).toBe(1);
 const control=hits.filter(h=>h.phase==='control');expect(control.map(h=>h.kind).sort()).toEqual(['destination','secondary']);
 await page.locator('#control').evaluate(e=>e.remove());
 await page.route('**/api/artifacts/export',route=>route.fulfill({contentType:'application/json',body:JSON.stringify({success:true,data:{html:canonical,filename:'local-q9.html',generatedAt:'2026-10-02T00:00:00Z',governanceState:'DRAFT_UNACCEPTED',verification:[]}})}));
 await seedStorage(page);await login(page);await page.evaluate(()=>localStorage.setItem('cvf_language','en'));await page.goto('/artifacts');phase='actual-before-build';
 await page.getByLabel('Title').fill('Local Q9');await page.getByRole('button',{name:/Build HTML/i}).click();
 const iframe=page.locator('iframe[title="Preview"]');const f=page.frameLocator('iframe[title="Preview"]');
 await expect(f.getByRole('heading',{name:'LOCAL_Q9_READABLE'})).toBeVisible();
 const parentUrl=page.url();await f.locator('html').evaluate(()=>{(window as any).__localQ9='retained'});
 await f.locator('#q9-link').click();await f.locator('#q9-link').click({modifiers:['Control']});await page.waitForTimeout(1200);
 await f.locator('#select').click({clickCount:3});const selected=await f.locator('html').evaluate(()=>window.getSelection()?.toString());expect(selected).toContain('LOCAL_Q9_SELECTABLE_TEXT');
 const box=await iframe.boundingBox();expect(box).not.toBeNull();await page.mouse.move(box!.x+box!.width/2,box!.y+box!.height/2);await page.mouse.wheel(0,2500);await page.waitForTimeout(400);
 const scrolled=await f.locator('html').evaluate(()=>document.scrollingElement?.scrollTop);expect(scrolled).toBeGreaterThan(0);
 const observation={hits:hits.filter(h=>h.phase==='actual-before-build'),unexpected,pages:context.pages().length,parentUrlUnchanged:page.url()===parentUrl,sandbox:await iframe.getAttribute('sandbox'),origin:await f.locator('html').evaluate(()=>location.origin),marker:await f.locator('html').evaluate(()=>(window as any).__localQ9),href:await f.locator('#q9-link').getAttribute('href'),color:await f.locator('h1').evaluate(e=>getComputedStyle(e).color),script:await f.locator('html').getAttribute('data-q9script'),selected,scrolled,policyRetained:(await iframe.getAttribute('srcdoc'))!.includes(policy)};
 writeFileSync('.next/cvf-navigation-local-review/observations.json',JSON.stringify({browser:browser.version(),canonical,control,observation},null,2));
 expect(observation.hits).toEqual([]);expect(unexpected).toEqual([]);expect(observation.pages).toBe(1);expect(observation.parentUrlUnchanged).toBe(true);expect(observation.sandbox).toBe('');expect(observation.origin).toBe('null');expect(observation.marker).toBe('retained');expect(observation.href).toBeNull();expect(observation.color).toBe('rgb(61, 72, 83)');expect(observation.script).toBeNull();expect(observation.policyRetained).toBe(true);
 console.log('LOCAL_Q9 '+JSON.stringify({control,observation}));
});
